package pl.zagranietyper.service;import org.junit.jupiter.api.Test;import pl.zagranietyper.model.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FootballTeamStatisticComparisonSettlementEngineTest {private final FootballTeamStatisticComparisonSettlementEngine e=new FootballTeamStatisticComparisonSettlementEngine();private final FootballTeamStatisticComparisonCondition c=new FootballTeamStatisticComparisonCondition(FootballFixtureStatisticType.CORNERS,FootballFixtureStatisticsSnapshot.TeamSide.HOME,FootballTeamStatisticComparisonCondition.Relation.MORE_THAN_OPPONENT);@Test void settlesMoreLessAndEquality(){assertEquals(SettlementDecision.W,e.settle(c,s(k(5,"HOME"),k(3,"AWAY"))).decision());assertEquals(SettlementDecision.L,e.settle(c,s(k(2,"HOME"),k(3,"AWAY"))).decision());assertEquals(SettlementDecision.UNSUPPORTED,e.settle(c,s(k(3,"HOME"),k(3,"AWAY"))).decision());}@Test void missingOrAbsentNeverMeansZero(){assertEquals(SettlementDecision.UNSUPPORTED,e.settle(c,s(k(3,"HOME"))).decision());assertEquals(SettlementDecision.UNSUPPORTED,e.settle(c,s(k(3,"HOME"),new FootballFixtureStatisticsSnapshot.StatisticValue(2,FootballFixtureStatisticsSnapshot.TeamSide.AWAY,FootballFixtureStatisticType.CORNERS,null,FootballFixtureStatisticsSnapshot.ValueStatus.ABSENT,"x"))).decision());}private static FootballFixtureStatisticsSnapshot.StatisticValue k(int n,String side){return new FootballFixtureStatisticsSnapshot.StatisticValue(side.equals("HOME")?1:2,FootballFixtureStatisticsSnapshot.TeamSide.valueOf(side),FootballFixtureStatisticType.CORNERS,BigDecimal.valueOf(n),FootballFixtureStatisticsSnapshot.ValueStatus.KNOWN,"x");}private static FootballFixtureStatisticsSnapshot s(FootballFixtureStatisticsSnapshot.StatisticValue...v){return new FootballFixtureStatisticsSnapshot(1,FootballFixtureStatisticsSnapshot.FetchStatus.COMPLETE,"x",200,2,null,Set.of(),"{}",Instant.EPOCH,1,List.of(v));}}
